return {["奈何桥"]={["1"]={["advice"]=0,["age"]=41,["blandishments"]=1,["desc"]=[[他年幼时被父母抛弃，变成了一名乞丐，苟且偷生数十载，最终冻死在街头。]],["force"]=0,["honest"]=0,["id"]=1,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[蓬头垢面，浑身是泥]],["sex"]=[[男]],["talkText"]=[[YEL$x:我这一世孤苦伶仃，无依无靠，就算知你是花言巧语又如何，唉..;CYN$x他喝下孟婆汤，默默走向奈何桥。]]},["10"]={["advice"]=1,["age"]=27,["blandishments"]=0,["desc"]=[[他出生武学世家，粗通拳脚，好打抱不平，却因武学不精死于山贼刀下。]],["force"]=0,["honest"]=0,["id"]=10,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_104]],["looks"]=[[身强体壮，面色红润]],["sex"]=[[男]],["talkText"]=[[YEL$x:十八年后我又是一条好汉！;CYN$x喝下孟婆汤，大步走向奈何桥。]]},["100"]={["advice"]=0,["age"]=56,["blandishments"]=0,["desc"]=[[他一生辛勤劳作，幸福离世。]],["force"]=0,["honest"]=0,["id"]=100,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]]},["101"]={["advice"]=0,["age"]=54,["blandishments"]=0,["desc"]=[[他一生碌碌无为，平淡离世。]],["force"]=0,["honest"]=0,["id"]=101,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]]},["102"]={["advice"]=0,["age"]=67,["blandishments"]=0,["desc"]=[[他一生富贵荣华，寿终正寝。]],["force"]=0,["honest"]=0,["id"]=102,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面带红光，体态丰腴]],["sex"]=[[男]]},["103"]={["advice"]=0,["age"]=43,["blandishments"]=0,["desc"]=[[他一生孤苦无依，饿死街头。]],["force"]=0,["honest"]=0,["id"]=103,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面黄肌瘦，双眼无神]],["sex"]=[[男]]},["104"]={["advice"]=0,["age"]=38,["blandishments"]=0,["desc"]=[[他一生平平淡淡，因病而逝。]],["force"]=0,["honest"]=0,["id"]=104,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相清秀，穿着书生布衣]],["sex"]=[[男]]},["105"]={["advice"]=0,["age"]=29,["blandishments"]=0,["desc"]=[[他戎马一生，最终战死沙场。]],["force"]=0,["honest"]=0,["id"]=105,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_103]],["looks"]=[[剑眉星目，浑身杀气]],["sex"]=[[男]]},["106"]={["advice"]=0,["age"]=36,["blandishments"]=0,["desc"]=[[他一生无甚建树，孤独终老。]],["force"]=0,["honest"]=0