],["force"]=0,["honest"]=0,["id"]=228,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面如冠玉，眉若刀裁]],["sex"]=[[男]]},["229"]={["advice"]=0,["age"]=65,["blandishments"]=0,["desc"]=[[他一生风平浪静，寿终正寝。]],["force"]=0,["honest"]=0,["id"]=229,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相普通，身上打着补丁]],["sex"]=[[男]]},["23"]={["advice"]=0,["age"]=37,["blandishments"]=1,["desc"]=[[他年幼时便霸道横行，长大后专行杀人放火之事，是一名令人闻风丧胆的江洋大盗，死于官府追捕。]],["force"]=0,["honest"]=0,["id"]=23,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_104]],["looks"]=[[满脸横肉，凶神恶煞]],["sex"]=[[男]],["talkText"]=[[YEL$x:他娘的，快把汤给我，老子等着投胎做好汉呢！;CYN$x喝下孟婆汤，大摇大摆走向奈何桥。]]},["230"]={["advice"]=0,["age"]=56,["blandishments"]=0,["desc"]=[[他一生辛勤劳作，幸福离世。]],["force"]=0,["honest"]=0,["id"]=230,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]]},["231"]={["advice"]=0,["age"]=54,["blandishments"]=0,["desc"]=[[他一生碌碌无为，平淡离世。]],["force"]=0,["honest"]=0,["id"]=231,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]]},["232"]={["advice"]=0,["age"]=67,["blandishments"]=0,["desc"]=[[他一生富贵荣华，寿终正寝。]],["force"]=0,["honest"]=0,["id"]=232,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面带红光，体态丰腴]],["sex"]=[[男]]},["233"]={["advice"]=0,["age"]=43,["blandishments"]=0,["desc"]=[[他一生孤苦无依，饿死街头。]],["force"]=0,["honest"]=0,["id"]=233,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面黄肌瘦，双眼无神]],["sex"]=[[男]]},["234"]={["advice"]=0,["age"]=38,["blandishments"]=0,["desc"]=[[他一生平平淡淡，因病而逝。]],["force"]=0,["honest"]=0,["id"]=234,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相清秀，穿着书生布衣]],["sex"]=[[男]]},["235"]={["advice"]=0,["age"]=29,["blandishments"]=0,["desc"]=[[他戎马一生，最终战死沙场。]],["force"]=0,["honest"]=0,["id"]=235,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_103]],["looks"]=[[剑眉星目，浑身杀气]],["sex"]=[[男]]},["236"]={["advice"]=0,["age"]=36,["blandishments"]=0,["desc"]=[[他一生无甚建树，孤独终老。]],["force"]=0,["honest"]=0,["id"]=236,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[瘦骨如柴，面颊突出]],["sex"]=[[男]]},["237"]={["advice"]=0,["age"]=51,["blandishments"]=0,["desc"]=[[他一生平淡无奇，死于意外。]],["force"]=0,["honest"]=0,["id"]=237,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[穿着朴素，白白净净]],["sex"]=[[男]]},["238"]={["advice"]=0,["age"]=25,["blandishments"]=0,["desc"]=[[他一生毫无波澜，因病而逝。]],["force"]=0,["honest"]=0,["id"]=238,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面如冠玉，眉若刀裁]],["sex"]=[[男]]},["239"]={["advice"]=0,["age"]=65,["blandishments"]=0,["desc"]=[[他一生风平浪静，寿终正寝。]],["force"]=0,["honest"]=0,["id"]=239,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相普通，身上打着补丁]],["sex"]=[[男]]},["24"]={["advice"]=1,["age"]=23,["blandishments"]=0,["desc"]=[[他家境微寒，被父母卖入梨园，却因天赋异禀成为江南赫赫有名的花旦，死于肺痨。]],["force"]=0,["honest"]=1,["id"]=24,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[不落烟尘，眉目如画]],["sex"]=[[男]],["talkText"]=[[YEL$x:我一生唱戏，这一生都活的很精彩，我不后悔，多谢阁下相告。;CYN$x喝下孟婆汤，走向奈何桥。]]},["240"]={["advice"]=0,["age"]=56,["blandishments"]=0,["desc"]=[[他一生辛勤劳作，幸福离世。]],["force"]=0,["honest"]=0,["id"]=240,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]]},["25"]={["advice"]=0,["age"]=43,["blandishments"]=0,["desc"]=[[他家道中落，流落街头被丐帮收留，一生行侠仗义快意恩仇，终得善终。]],["force"]=0,["honest"]=1,["id"]=25,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_105]],["looks"]=[[浓眉大眼，一脸正气]],["sex"]=[[男]],["talkText"]=[[YEL$x:我这辈子没留下什么遗憾，就是舍不得我那些兄弟们。;CYN$x喝下孟婆汤，走向奈何桥。]]},["26"]={["advice"]=0,["age"]=11,["blandishments"]=1,["desc"]=[[他与父亲以卖艺维生，清贫而常乐，死于一次卖艺的意外失足。]],["force"]=0,["honest"]=0,["id"]=26,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[稚气未脱，眸如星辰]],["sex"]=[[男]],["talkText"]=[[YEL$x:我不难过，只是，我死了，爹爹靠什么为生呢。;CYN$x喝下孟婆汤，走向奈何桥。]]},["27"]={["advice"]=0,["age"]=70,["blandishments"]=0,["desc"]=[[他出生时满室檀香，幼年便出了家，一生求佛悟禅，无争无求，自主坐化。]],["force"]=0,["honest"]=1,["id"]=27,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[朗目疏眉，气质出尘]],["sex"]=[[男]],["talkText"]=[[YEL$x:这便是轮回么，看来贫僧依未看破啊...;CYN$x喝下孟婆汤，慢慢走向奈何桥。]]},["28"]={["advice"]=0,["age"]=56,["blandishments"]=0,["desc"]=[[他家里世代行医，一心悬壶济世，拯救苍生无数，妻子和睦，一生安稳。]],["force"]=0,["honest"]=1,["id"]=28,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[双鬓微白，面目慈祥]],["sex"]=[[男]],["talkText"]=[[YEL$x:我过得很满足，是时候去了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["29"]={["advice"]=0,["age"]=34,["blandishments"]=0,["desc"]=[[他出生于齐鲁一带的摸金世家，一生所盗墓穴无数，终遭报应，死于流沙机关之中。]],["force"]=0,["honest"]=0,["id"]=29,["inducement"]=1,["intimidate"]=1,["level"]=[[npc201_104]],["looks"]=[[眉目淡淡，眼神躲闪]],["sex"]=[[男]],["talkText"]=[[YEL$x:我还不想投胎，我的盗墓技艺还未能有传人。;CYN$x被逼喝下孟婆汤，走向奈何桥。]]},["3"]={["advice"]=1,["age"]=25,["blandishments"]=0,["desc"]=[[他年幼家境贫寒，成年之后被征入伍，最后死于战场之上。]],["force"]=0,["honest"]=0,["id"]=3,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_104]],["looks"]=[[身材高大，面色发白]],["sex"]=[[男]],["talkText"]=[[YEL$x:唉，我唯一放心不下的就是我那老母亲，罢了罢了，来世若有机会再报我母亲的恩吧。;CYN$x喝下孟婆汤，走向奈何桥。]]},["30"]={["advice"]=1,["age"]=7,["blandishments"]=1,["desc"]=[[他出生皇族，天生体弱多病，早早夭折。]],["force"]=0,["honest"]=0,["id"]=30,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[稚气未脱，面色发黄]],["sex"]=[[男]],["talkText"]=[[YEL$x:我不要自己喝！你来喂我！;CYN你喂$x喝下孟婆汤，$x走向奈何桥。]]},["31"]={["advice"]=0,["age"]=52,["blandishments"]=0,["desc"]=[[他父辈是黄河摆渡人，长成后继承祖业老实度日，因水鬼掀船溺毙。]],["force"]=0,["honest"]=1,["id"]=31,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]],["talkText"]=[[YEL$x:我向菩萨请愿过了，水鬼已经被超度了，我也能安心去了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["32"]={["advice"]=0,["age"]=51,["blandishments"]=0,["desc"]=[[他父辈富可敌国，靠钱财买来官职，一生欺压百姓，贪赃枉法，死于仇家寻仇。]],["force"]=0,["honest"]=0,["id"]=32,["inducement"]=1,["intimidate"]=1,["level"]=[[npc201_102]],["looks"]=[[相貌奇丑，脑满肠肥]],["sex"]=[[男]],["talkText"]=[[YEL$x:别..别这样，我好不甘心！真的不甘心！;CYN$x被逼喝下孟婆汤，快步走向奈何桥。]]},["33"]={["advice"]=1,["age"]=37,["blandishments"]=0,["desc"]=[[他出生在一个铁匠之家，学了一手制造武器的好手艺，却因妻子不和被其情人杀死。]],["force"]=0,["honest"]=0,["id"]=33,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[四肢粗壮，皮肤黝黑]],["sex"]=[[男]],["talkText"]=[[YEL$x:多谢朋友劝告，我对这世间本来也没啥牵挂了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["34"]={["advice"]=0,["age"]=54,["blandishments"]=0,["desc"]=[[她出生书香门第，是有名的才女，嫁给一名才子，郎才女貌，幸福终老。]],["force"]=0,["honest"]=1,["id"]=34,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[明眸皓齿，气质出众]],["sex"]=[[女]],["talkText"]=[[YEL$x:我这一生很幸福，希望来生也能如此。;CYN$x喝下孟婆汤，走向奈何桥。]]},["35"]={["advice"]=1,["age"]=21,["blandishments"]=0,["desc"]=[[她是一名采桑女，生活清贫但美好，嫁给一名酒鬼丈夫之后被丈夫毒打致死。]],["force"]=0,["honest"]=0,["id"]=35,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相清秀，面有泪痕]],["sex"]=[[女]],["talkText"]=[[YEL$x:我没有心愿未了，只是恨当初不该嫁给他。;CYN$x喝下孟婆汤，走向奈何桥。]]},["36"]={["advice"]=1,["age"]=17,["blandishments"]=0,["desc"]=[[她原本出生官宦之家，琴棋书画样样精通，父亲被诬下狱，家中老小全部贬为奴籍，她被卖到青楼，不肯卖身自缢而亡。]],["force"]=0,["honest"]=0,["id"]=36,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[生得沉鱼落雁，面色忧郁]],["sex"]=[[女]],["talkText"]=[[YEL$x:世间纷纷扰扰，来生愿不为人。;CYN$x喝下孟婆汤，慢慢走向奈何桥。]]},["37"]={["advice"]=0,["age"]=19,["blandishments"]=0,["desc"]=[[她生前是一名公主，娇生惯养，蛮横无理，成为皇族纷争的受害者。]],["force"]=1,["honest"]=0,["id"]=37,["inducement"]=0,["intimidate"]=1,["level"]=[[npc201_102]],["looks"]=[[俏皮可爱，古灵精怪]],["sex"]=[[女]],["talkText"]=[[YEL$x:你敢凶我！我父皇都不敢凶我！我要找我父皇...;CYN$x被逼喝下孟婆汤，走向奈何桥。]]},["38"]={["advice"]=0,["age"]=62,["blandishments"]=0,["desc"]=[[她出身贫寒，靠卖油炸豆腐为生，丈夫患病多年不离不弃，最后寿终而亡。]],["force"]=0,["honest"]=1,["id"]=38,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目慈祥，发白如雪]],["sex"]=[[女]],["talkText"]=[[YEL$x:我很幸福。感谢我能有机会做人。;CYN$x喝下孟婆汤，走向奈何桥。]]},["39"]={["advice"]=0,["age"]=15,["blandishments"]=1,["desc"]=[[她出身在边关，家乡常遭掠劫，她流落街头乞讨为生，感染霍乱而死。]],["force"]=0,["honest"]=0,["id"]=39,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[蓬头垢面，浑身是泥]],["sex"]=[[女]],["talkText"]=[[YEL$x:我这辈子苦难不断，死了连你也花言巧语来哄骗我。;CYN$x喝下孟婆汤，走向奈何桥。]]},["4"]={["advice"]=0,["age"]=45,["blandishments"]=0,["desc"]=[[他生于一贫穷人家，长大后做了一名瓦匠，性格胆小，好在妻贤子孝，一生平淡却也充足，最后死于风寒。]],["force"]=0,["honest"]=0,["id"]=4,["inducement"]=0,["intimidate"]=1,["level"]=[[npc201_102]],["looks"]=[[相貌平平，穿着朴素]],["sex"]=[[男]],["talkText"]=[[YEL$x:别..别打我，我喝就是了，其实我早已知晓我自己的情况，我这一生已了无牵挂，是该投胎了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["40"]={["advice"]=0,["age"]=27,["blandishments"]=0,["desc"]=[[她家中经营染坊，成日懒惰不做活，因染坊大火而死。]],["force"]=1,["honest"]=0,["id"]=40,["inducement"]=0,["intimidate"]=1,["level"]=[[npc201_101]],["looks"]=[[面如无盐，歪鼻斜眼]],["sex"]=[[女]],["talkText"]=[[YEL$x:大侠饶命！我喝还不行吗！;CYN$x被逼喝下孟婆汤，走向奈何桥。]]},["41"]={["advice"]=0,["age"]=18,["blandishments"]=1,["desc"]=[[她家境一般，擅女红，因想在乞巧节讨得达官贵人欢心日以继夜劳作刺绣，过劳吐血而死。]],["force"]=0,["honest"]=0,["id"]=41,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌平平，面色蜡黄]],["sex"]=[[女]],["talkText"]=[[YEL$x:可惜了我的刺绣。;CYN$x喝下孟婆汤，走向奈何桥。]]},["42"]={["advice"]=0,["age"]=23,["blandishments"]=0,["desc"]=[[她父亲是猎人，生的她豪爽开朗，百步穿杨，嫁与一名将军，夫妻二人同在战场上战死。]],["force"]=0,["honest"]=1,["id"]=42,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_104]],["looks"]=[[器宇轩昂，月貌花容]],["sex"]=[[女]],["talkText"]=[[YEL$x:我这辈子活得够精彩啦。;CYN$x喝下孟婆汤，大步走向奈何桥。]]},["43"]={["advice"]=1,["age"]=19,["blandishments"]=0,["desc"]=[[她儿时被母亲卖入宫中，被皇帝偶然临幸怀上龙嗣，却因胆小怕事不敢声张而被妒妃害死。]],["force"]=0,["honest"]=1,["id"]=43,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[月貌花容，楚楚动人]],["sex"]=[[女]],["talkText"]=[[YEL$x:我知道必须走了，只是舍不得我的孩子...;CYN$x喝下孟婆汤，缓缓走向奈何桥。]]},["44"]={["advice"]=1,["age"]=17,["blandishments"]=0,["desc"]=[[她家境殷实，父亲在朝为官，因爱上贫穷书生并与之私奔被父亲追杀，双双跳崖而亡。]],["force"]=0,["honest"]=1,["id"]=44,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[明眸皓齿，温柔可人]],["sex"]=[[女]],["talkText"]=[[YEL$x:他已经先走了吗…我也来了。来生再见。;CYN$x喝下孟婆汤，走向奈何桥。]]},["45"]={["advice"]=1,["age"]=54,["blandishments"]=1,["desc"]=[[她出生巫蛊之族，擅以蛊虫害人救人，被乡人敬而远之，孤独终老。]],["force"]=0,["honest"]=0,["id"]=45,["inducement"]=1,["intimidate"]=1,["level"]=[[npc201_102]],["looks"]=[[面目苍老，双眼无神]],["sex"]=[[女]],["talkText"]=[[YEL$x:你..你.你,别乱来，喝就喝，反正这世间没什么好留念的。;CYN$x被逼喝下孟婆汤，走向奈何桥。]]},["46"]={["advice"]=0,["age"]=57,["blandishments"]=0,["desc"]=[[她是一名船娘，因长相清秀被一富商娶回家，成为一名贤妻良母，幸福终老。]],["force"]=0,["honest"]=1,["id"]=46,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目慈祥，发白如雪]],["sex"]=[[女]],["talkText"]=[[YEL$x:我知足了，只是有些舍不得老伴。;CYN$x喝下孟婆汤，走向奈何桥。]]},["47"]={["advice"]=1,["age"]=32,["blandishments"]=0,["desc"]=[[她家中经营乐器店，一手琵琶惊艳世人，生前留下大量乐谱，因先天心疾去世。]],["force"]=0,["honest"]=0,["id"]=47,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[如出水芙蓉，清丽脱俗]],["sex"]=[[女]],["talkText"]=[[YEL$x:高山流水，曲高和寡，此生知音难寻。;CYN$x喝下孟婆汤，走向奈何桥。]]},["48"]={["advice"]=0,["age"]=27,["blandishments"]=0,["desc"]=[[她父母双亡，被峨眉收留，心地善良，下山救治瘟疫时不幸身亡。]],["force"]=0,["honest"]=1,["id"]=48,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_104]],["looks"]=[[如出水芙蓉，清丽脱俗]],["sex"]=[[女]],["talkText"]=[[YEL$x:我没有双亲，本已无所牵挂，师父的恩情，只有来生再报了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["49"]={["advice"]=0,["age"]=36,["blandishments"]=0,["desc"]=[[她出生在沿海贫穷人家，被倭人掳去，终日郁郁寡欢，对家乡思念成疾，最终身亡。]],["force"]=0,["honest"]=1,["id"]=49,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相清秀，面有泪痕]],["sex"]=[[女]],["talkText"]=[[YEL$x:我回到故土了，太好了...;CYN$x喝下孟婆汤，走向奈何桥。]]},["5"]={["advice"]=0,["age"]=33,["blandishments"]=0,["desc"]=[[他生于一贫穷人家，梦想成为富有之人，整日游手好闲，最后死于意外。]],["force"]=0,["honest"]=0,["id"]=5,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[贼眉鼠眼，到处东张西望]],["sex"]=[[男]],["talkText"]=[[YEL$x:哇，这么多钱，我从小就想当个有钱人，今日得偿所愿，也是时候走了。;CYN$x喝下孟婆汤，面带笑容走向奈何桥。]]},["50"]={["advice"]=1,["age"]=21,["blandishments"]=0,["desc"]=[[她是家中独女，从小当做男儿养，因失足落马不治身亡。]],["force"]=0,["honest"]=0,["id"]=50,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[剑眉星目，不输男子]],["sex"]=[[女]],["talkText"]=[[YEL$x:阿黄平日很乖，怎么会把我摔死了呢。;CYN$x喝下孟婆汤，走向奈何桥。]]},["51"]={["advice"]=0,["age"]=66,["blandishments"]=0,["desc"]=[[她出生于小乡村，务农为生，嫁给青梅竹马，子女成群，平淡地过完一生。]],["force"]=0,["honest"]=1,["id"]=51,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目慈祥，发白如雪]],["sex"]=[[女]],["talkText"]=[[YEL$x:我已经很满足了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["52"]={["advice"]=0,["age"]=70,["blandishments"]=0,["desc"]=[[她家境殷实，嫁给一名修鞋匠，平淡幸福，丈夫去世之后她也服毒药相随。]],["force"]=0,["honest"]=1,["id"]=52,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目慈祥，发白如雪]],["sex"]=[[女]],["talkText"]=[[YEL$x:我已在地府与他团圆，心愿已了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["53"]={["advice"]=1,["age"]=32,["blandishments"]=0,["desc"]=[[大夫庆封的后代。喜好读书击剑，为人慷慨侠义。入宫刺秦未遂身死。]],["force"]=0,["honest"]=1,["id"]=53,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_105]],["looks"]=[[剑眉星目，风采出众]],["name"]=[[荆轲]],["sex"]=[[男]],["talkText"]=[[YEL$x:我未能完成太子丹使命，九死亦难赎其罪也。;CYN$x喝下孟婆汤，走向奈何桥。]]},["54"]={["advice"]=0,["age"]=62,["blandishments"]=0,["desc"]=[[出身于楚宗室贵族，博闻强志，志向远大。提倡“美政”，受到排挤。楚都破后投江而亡。]],["force"]=0,["honest"]=1,["id"]=54,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[鹤发童颜，满脸忧愁]],["name"]=[[屈原]],["sex"]=[[男]],["talkText"]=[[YEL$x:路漫漫其修远兮，吾将上下而求索。;CYN$x喝下孟婆汤，走向奈何桥。]]},["55"]={["advice"]=0,["age"]=34,["blandishments"]=0,["desc"]=[[颍川城父人，善谋略，精通黄老之道，不愿为官，生性淡泊。]],["force"]=0,["honest"]=1,["id"]=55,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[面如冠玉，羽扇纶巾]],["name"]=[[张良]],["sex"]=[[男]],["talkText"]=[[YEL$x:可惜，黄石公三略怕是要失传了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["56"]={["advice"]=0,["age"]=38,["blandishments"]=0,["desc"]=[[五原郡九原县人，勇猛世无双，贪婪多变，与曹操对战战败被俘身亡。]],["force"]=0,["honest"]=1,["id"]=56,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_107]],["looks"]=[[身高九尺，气若鬼神]],["name"]=[[吕布]],["sex"]=[[男]],["talkText"]=[[YEL$x:曹操老贼！下辈子绝不放过你！;CYN$x喝下孟婆汤，快步走向奈何桥。]]},["57"]={["advice"]=0,["age"]=39,["blandishments"]=0,["desc"]=[[河东王氏，状元及第。参禅悟理，学庄信道，精通诗、书、画、音乐等，世称“王右丞”。]],["force"]=0,["honest"]=1,["id"]=57,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[穿的干干净净，一脸与世无争]],["name"]=[[王维]],["sex"]=[[男]],["talkText"]=[[YEL$x:山中相送罢，日暮掩柴扉。春草明年绿，王孙归不归？;CYN$x喝下孟婆汤，走向奈何桥。]]},["58"]={["advice"]=1,["age"]=25,["blandishments"]=0,["desc"]=[[少年入洛阳，才华横溢，丰神俊秀。被牵连进谋害太子的阴谋中，身死，夷三族。]],["force"]=0,["honest"]=1,["id"]=58,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[生如玉璧，恍然如仙人]],["name"]=[[潘岳]],["sex"]=[[男]],["talkText"]=[[YEL$x:孑然一身，无甚牵挂。;CYN$x喝下孟婆汤，走向奈何桥。]]},["59"]={["advice"]=0,["age"]=40,["blandishments"]=0,["desc"]=[[年幼时因岭南流人谋反案年幼被阉割。后追随李隆基不离不弃，李隆基死后吐血而亡。]],["force"]=0,["honest"]=1,["id"]=59,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[长相普通，面白无须]],["name"]=[[高力士]],["sex"]=[[男]],["talkText"]=[[YEL$x:皇上，臣这就追随您来了。;CYN$x喝下孟婆汤，快步走向奈何桥。]]},["6"]={["advice"]=0,["age"]=51,["blandishments"]=0,["desc"]=[[他出身贫寒，十年寒窗苦读考中进士，成为一方父母官护佑百姓，最终善终。]],["force"]=0,["honest"]=1,["id"]=6,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[眉目清秀，身材挺拔]],["sex"]=[[男]],["talkText"]=[[YEL$x:我想要的都已得到，已经无甚牵挂了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["60"]={["advice"]=1,["age"]=67,["blandishments"]=0,["desc"]=[[精通医术，擅长外科手术。晚年因遭曹操怀疑，下狱被拷问致死。]],["force"]=0,["honest"]=0,["id"]=60,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[鬓发如雪，浑身散发着药香]],["name"]=[[华佗]],["sex"]=[[男]],["talkText"]=[[YEL$x:救得了世人，却救不了自己。;CYN$x喝下孟婆汤，走向奈何桥。]]},["61"]={["advice"]=0,["age"]=43,["blandishments"]=1,["desc"]=[[生性狡诈，力主宋金议和。他极力贬斥抗金将士，阻止恢复；同时结纳私党，斥逐异己，屡兴大狱，后病逝。]],["force"]=1,["honest"]=0,["id"]=61,["inducement"]=1,["intimidate"]=1,["level"]=[[npc201_101]],["looks"]=[[贼眉鼠目，面目可憎]],["name"]=[[秦桧]],["sex"]=[[男]],["talkText"]=[[YEL$x:我不要投胎，我的荣华富贵...;CYN$x被逼喝下孟婆汤，走向奈何桥。]]},["62"]={["advice"]=1,["age"]=39,["blandishments"]=0,["desc"]=[[为曹魏宗室的女婿，官至中散大夫，世称“嵇中散”。后隐居不仕，屡拒为官。因得罪钟会，遭其构陷，而被司马昭处死。]],["force"]=0,["honest"]=0,["id"]=62,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[眉目如画，气质出众]],["name"]=[[嵇康]],["sex"]=[[男]],["talkText"]=[[YEL$x:可惜啊，《广陵散》从此便失传了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["63"]={["advice"]=1,["age"]=22,["blandishments"]=0,["desc"]=[[号太真。姿质丰艳，善歌舞，通音律，与李隆基恩爱非常。在马嵬驿死于乱军之中，香消玉殒。]],["force"]=0,["honest"]=1,["id"]=63,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[倾国倾城，遗世而独立]],["name"]=[[杨玉环]],["sex"]=[[女]],["talkText"]=[[YEL$x:皇上，你我生死与共，臣妾先走一步了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["64"]={["advice"]=1,["age"]=29,["blandishments"]=0,["desc"]=[[号易安居士，出生于书香门第，早期生活优裕，流寓南方，境遇孤苦，病逝。]],["force"]=0,["honest"]=0,["id"]=64,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[楚楚动人，面色微白]],["name"]=[[李清照]],["sex"]=[[女]],["talkText"]=[[YEL$x:莫道不消魂，帘卷西风，人比黄花瘦。;CYN$x喝下孟婆汤，走向奈何桥。]]},["65"]={["advice"]=1,["age"]=21,["blandishments"]=0,["desc"]=[[号“香扇坠”，音律诗词无一不通，嫁人之后因出身低贱，被歧视，郁郁寡欢无奈患上肺痨而死，]],["force"]=0,["honest"]=0,["id"]=65,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[沉鱼落雁，风华绝代]],["name"]=[[李香君]],["sex"]=[[女]],["talkText"]=[[YEL$x:侯郎，来生我还愿伴你一生。;CYN$x喝下孟婆汤，走向奈何桥。]]},["66"]={["advice"]=0,["age"]=34,["blandishments"]=0,["desc"]=[[刘秀原配，名相管仲后裔，貌美绝伦，恭谨俭约，仁爱孝顺，怜悯慈爱。后病逝。]],["force"]=0,["honest"]=1,["id"]=66,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[朱唇粉面，玉貌花容]],["name"]=[[阴丽华]],["sex"]=[[女]],["talkText"]=[[YEL$x:无论再来几世，我都只会做秀的妻子。;CYN$x喝下孟婆汤，走向奈何桥。]]},["67"]={["advice"]=0,["age"]=24,["blandishments"]=0,["desc"]=[[巨商卓王孙之女，姿色娇美，精通音律，善弹琴，有文名。与司马相如比翼连枝，善终。]],["force"]=0,["honest"]=1,["id"]=67,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[朱唇粉面，玉貌花容]],["name"]=[[卓文君]],["sex"]=[[女]],["talkText"]=[[YEL$x:愿得一心人，白头不相离。;CYN$x喝下孟婆汤，走向奈何桥。]]},["68"]={["advice"]=1,["age"]=23,["blandishments"]=0,["desc"]=[[有“巾帼宰相”之名，聪慧善文，李隆基起兵发动唐隆政变，与韦后同时被杀。]],["force"]=0,["honest"]=0,["id"]=68,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[朱唇粉面，玉貌花容]],["name"]=[[上官婉儿]],["sex"]=[[女]],["talkText"]=[[YEL$x:来世希望只做一名平凡女子。;CYN$x喝下孟婆汤，走向奈何桥。]]},["69"]={["advice"]=0,["age"]=26,["blandishments"]=0,["desc"]=[[巾帼英雄，忠孝节义，代父从军击败入侵民族而流传千古。]],["force"]=0,["honest"]=1,["id"]=69,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_105]],["looks"]=[[棱角分明，气质不输男儿]],["name"]=[[花木兰]],["sex"]=[[女]],["talkText"]=[[YEL$x:替父从军虽然为我赢得了名声，却也让我失去了很多。愿来生不再战乱。;CYN$x喝下孟婆汤，走向奈何桥。]]},["7"]={["advice"]=1,["age"]=32,["blandishments"]=0,["desc"]=[[他生于书香门第，一生顺风顺水，成为琴师之后，却因性格孤傲受排挤郁郁死去。]],["force"]=0,["honest"]=0,["id"]=7,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[丰神俊秀，气质超凡]],["sex"]=[[男]],["talkText"]=[[YEL$x:你说得对，我这一生活得从来不听别人劝告，没想到死后才明白这个道理，唉。;CYN$x喝下孟婆汤，默默走向奈何桥。]]},["70"]={["advice"]=0,["age"]=28,["blandishments"]=0,["desc"]=[[诸葛亮之妻，相貌丑陋，才华横溢，善终。]],["force"]=0,["honest"]=1,["id"]=70,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_102]],["looks"]=[[貌如无盐，其丑无比]],["name"]=[[黄月英]],["sex"]=[[女]],["talkText"]=[[YEL$x:他走了，我也该追随而去了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["71"]={["advice"]=0,["age"]=21,["blandishments"]=0,["desc"]=[[为家中三代报仇，学习飞檐走壁与刀剑武艺，后入宫杀死雍正。]],["force"]=0,["honest"]=1,["id"]=71,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_106]],["looks"]=[[朱唇粉面，玉貌花容]],["name"]=[[吕四娘]],["sex"]=[[女]],["talkText"]=[[YEL$x:大仇得报，心愿已了！;CYN$x喝下孟婆汤，走向奈何桥。]]},["72"]={["advice"]=1,["age"]=20,["blandishments"]=0,["desc"]=[[青楼歌姬，姿容清丽，能歌善舞，名动一时。]],["force"]=0,["honest"]=0,["id"]=72,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[沉鱼落雁，风华绝代]],["name"]=[[李师师]],["sex"]=[[女]],["talkText"]=[[YEL$x:来生愿为民家妇，不负东京唱新词。;CYN$x喝下孟婆汤，走向奈何桥。]]},["73"]={["advice"]=1,["age"]=43,["blandishments"]=0,["desc"]=[[他生前是一名捕快，鲜衣怒马，断案果决，却因此得罪权贵问斩。]],["force"]=0,["honest"]=0,["id"]=73,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_104]],["looks"]=[[生得相貌平平，一脸正气]],["sex"]=[[男]],["talkText"]=[[YEL$x:我从不后悔自己做的事，下辈子我还是会不向权贵低头。;CYN$x喝下孟婆汤，走向奈何桥。]]},["74"]={["advice"]=0,["age"]=54,["blandishments"]=0,["desc"]=[[他是一名剃头匠，以为人理发为生，一生勤勤恳恳，死于风寒。]],["force"]=0,["honest"]=1,["id"]=74,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[相貌丑陋，一脸老实]],["sex"]=[[男]],["talkText"]=[[YEL$x:俺是粗人，听不懂你这些大道理，反正俺也没什么好留恋的。;CYN$x喝下孟婆汤，走向奈何桥。]]},["75"]={["advice"]=0,["age"]=31,["blandishments"]=1,["desc"]=[[他自幼出家做了道士，以道士的名义到处招摇撞骗，入狱后病逝。]],["force"]=0,["honest"]=0,["id"]=75,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[吊眉斜眼，长相可怖]],["sex"]=[[男]],["talkText"]=[[YEL$x:我当然会喝，留在这又没什么好处。;CYN$x喝下孟婆汤，走向奈何桥。]]},["76"]={["advice"]=0,["age"]=21,["blandishments"]=0,["desc"]=[[他被刺客养大，行走于黑暗中，杀人无数，偏偏爱上要刺杀的女子，为了保护她万箭穿心而死。]],["force"]=0,["honest"]=1,["id"]=76,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_105]],["looks"]=[[丰神俊朗，杀气很重]],["sex"]=[[男]],["talkText"]=[[YEL$x:人生再来一次，我依旧不会后悔我的选择。;CYN$x喝下孟婆汤，走向奈何桥。]]},["77"]={["advice"]=1,["age"]=17,["blandishments"]=0,["desc"]=[[他生前是孤儿，靠偷盗养活自己，一次偷窃失手被乱棍打死。]],["force"]=0,["honest"]=0,["id"]=77,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[虽然满脸污泥，但眉目十分清秀]],["sex"]=[[男]],["talkText"]=[[YEL$x:来生希望我不要再活的这么艰苦了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["78"]={["advice"]=0,["age"]=41,["blandishments"]=0,["desc"]=[[他是一名诗人，饱腹诗书，纵情山水，因肺疾去世。]],["force"]=0,["honest"]=1,["id"]=78,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[长相普通，气质脱俗]],["sex"]=[[男]],["talkText"]=[[YEL$x:若能寻得一知己，则此生无憾矣。;CYN$x喝下孟婆汤，走向奈何桥。]]},["79"]={["advice"]=0,["age"]=56,["blandishments"]=0,["desc"]=[[他是一名花匠，心无大志，一心做好手中事，寿终正寝。]],["force"]=0,["honest"]=1,["id"]=79,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[身材瘦小，面目慈善]],["sex"]=[[男]],["talkText"]=[[YEL$x:我这辈子很满足。;CYN$x喝下孟婆汤，走向奈何桥。]]},["8"]={["advice"]=0,["age"]=45,["blandishments"]=0,["desc"]=[[他家里世代为农，继承祖业辛苦耕耘，老实过完一生，寿终正寝。]],["force"]=0,["honest"]=1,["id"]=8,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[土里土气，老实憨厚]],["sex"]=[[男]],["talkText"]=[[YEL$x:俺已经自足了，死了就死了吧。;CYN$x喝下孟婆汤，走向奈何桥。]]},["80"]={["advice"]=1,["age"]=23,["blandishments"]=0,["desc"]=[[他天生残疾无法行走，家人不离不弃，一生清贫而美满，旧疾复发而死。]],["force"]=0,["honest"]=0,["id"]=80,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[行走不便，杵着木棍]],["sex"]=[[男]],["talkText"]=[[YEL$x:我很幸福，只是有些放心不下家人。;CYN$x喝下孟婆汤，走向奈何桥。]]},["81"]={["advice"]=1,["age"]=16,["blandishments"]=0,["desc"]=[[他是一名私生子，苟且度日，被主母发现后惨遭杀害。]],["force"]=0,["honest"]=0,["id"]=81,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[稚气未脱，眉目如画]],["sex"]=[[男]],["talkText"]=[[YEL$x:死对我来说更像解脱。;CYN$x喝下孟婆汤，走向奈何桥。]]},["82"]={["advice"]=0,["age"]=36,["blandishments"]=1,["desc"]=[[他生前经营着一家酒店，时常在酒中掺水，被劫匪所杀。]],["force"]=0,["honest"]=0,["id"]=82,["inducement"]=1,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[贼头贼脑，四肢粗壮]],["sex"]=[[男]],["talkText"]=[[YEL$x:好说好说，我这就喝。;CYN$x喝下孟婆汤，走向奈何桥。]]},["83"]={["advice"]=0,["age"]=68,["blandishments"]=0,["desc"]=[[他是一名采参人，技艺高超，性格敦厚，年老采参时失足掉落山崖。]],["force"]=0,["honest"]=1,["id"]=83,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目苍老，弯腰驼背]],["sex"]=[[男]],["talkText"]=[[YEL$x:我活得够久了，差不多该走了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["84"]={["advice"]=0,["age"]=54,["blandishments"]=0,["desc"]=[[他生前是说书人，智慧通透，育有一子，寿终而亡。]],["force"]=0,["honest"]=1,["id"]=84,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目苍老，气质不减]],["sex"]=[[男]],["talkText"]=[[YEL$x:这就是冥府…可惜不能说给世人了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["85"]={["advice"]=0,["age"]=70,["blandishments"]=0,["desc"]=[[他是一名木匠，雕花技术高超，一生幸福美满，寿终正寝。]],["force"]=0,["honest"]=1,["id"]=85,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[面目苍老，弯腰驼背]],["sex"]=[[男]],["talkText"]=[[YEL$x:我没什么牵挂了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["86"]={["advice"]=1,["age"]=33,["blandishments"]=0,["desc"]=[[他是一名建筑工匠，手段绝伦，为皇帝修缮陵墓之后被活埋。]],["force"]=0,["honest"]=0,["id"]=86,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[身强体壮，相貌平平]],["sex"]=[[男]],["talkText"]=[[YEL$x:哎，早也是死晚也是死，反正都死了，我还能怎样呢。;CYN$x喝下孟婆汤，走向奈何桥。]]},["87"]={["advice"]=0,["age"]=51,["blandishments"]=0,["desc"]=[[他出生于农户之家，年幼时离家闯荡，后富甲一方衣锦还乡，病逝。]],["force"]=0,["honest"]=1,["id"]=87,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_101]],["looks"]=[[满面红光，眉疏目淡]],["sex"]=[[男]],["talkText"]=[[YEL$x:我这辈子活的精彩绝伦，是时候安心去了。;CYN$x喝下孟婆汤，走向奈何桥。]]},["88"]={["advice"]=0,["age"]=55,["blandishments"]=0,["desc"]=[[他生性好学，长成后成为一名夫子，桃李天下，因心疾去世。]],["force"]=0,["honest"]=1,["id"]=88,["inducement"]=0,["intimidate"]=0,["level"]=[[npc201_